// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

library BiggiPriceLibrary {
    struct BlockInformation {
        uint256 basePrice;       // Výchozí cena bloku (např. 100 ether)
        uint256 priceIncrease;   // Růst ceny v milióntinách (např. 10100000 = +1.00 %)
        uint256 currentPrice;    // Aktuální cena bloku
        uint16 mintCount;        // Kolik NFT už bylo mintnuto v tomto bloku
    }

    /// Inicializuje všech 10 bloků najednou
    function initializeBlocks(
        BlockInformation[10] storage blocks,
        uint256[10] memory basePrices,
        uint256[10] memory priceIncreases
    ) internal {
        for (uint8 i = 0; i < 10; i++) {
            blocks[i] = BlockInformation({
                basePrice: basePrices[i],
                priceIncrease: priceIncreases[i], // např. 10100000 = +1%
                currentPrice: basePrices[i],
                mintCount: 0
            });
        }
    }

    /// Zvyš aktuální cenu bloku po každém mintu podle jeho priceIncrease
    /// priceIncrease je v milióntinách (10_000_000 = 0% růst, 10_100_000 = 1% růst)
    function updatePrice(BlockInformation storage blockInformation) internal {
        blockInformation.currentPrice = (blockInformation.currentPrice * blockInformation.priceIncrease) / 10_000_000;
        blockInformation.mintCount++;
    }

    /// Vrací aktuální cenu bloku
    function getCurrentPrice(BlockInformation storage blockInformation) internal view returns (uint256) {
        return blockInformation.currentPrice;
    }

    /// Vrací počet mintů v tomto bloku
    function getMintCount(BlockInformation storage blockInformation) internal view returns (uint16) {
        return blockInformation.mintCount;
    }
}
